import{_ as i,o as t,c as a,a3 as s,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const d="/bilder/schueler/weitere-adressen1.png",o="/bilder/schueler/weitere-adressen2.png",l="/bilder/schueler/weitere-adressen4.png",u="/bilder/schueler/weitere-adressen3.png",w=JSON.parse('{"title":"Betriebe und weitere Adressen zuordnen","description":"","frontmatter":{"title":"Betriebe und weitere Adressen zuordnen","source_pageid":491,"source_revision":5919},"headers":[],"relativePath":"schild3/schueler/weitere-adressen-schueler.md","filePath":"schild3/schueler/weitere-adressen-schueler.md"}'),c={name:"schild3/schueler/weitere-adressen-schueler.md"};function g(h,r,m,p,b,A){return t(),a("div",null,[...r[0]||(r[0]=[s('<h1 id="betriebe-und-weitere-adressen-zuordnen" tabindex="-1">Betriebe und weitere Adressen zuordnen <a class="header-anchor" href="#betriebe-und-weitere-adressen-zuordnen" aria-label="Permalink to &quot;Betriebe und weitere Adressen zuordnen&quot;">​</a></h1><p>Ordnen Sie einer Schülerin oder einem Schüler weitere Adressen zu, etwa Ausbildungs- oder Praktikumsbetriebe. Pflegen Sie dazu Kontaktdaten, Ansprechpersonen und ergänzende Angaben.</p><p>Unter <em>Schüler</em> ➜ <strong>Weitere Adressen</strong> lassen sich für den Schüler relevante Adressen anlegen. Sinnvoll ist dies, um etwa Ausbildungsbetriebe oder Praktikumsbetriebe zu hinterlegen. Auch andere für den Schüler relevante Adressen, die nicht unter &quot;Erz. Berechtigte&quot; passen, können hier angelegt werden.</p><h2 id="adressen-einem-lernenden-zuordnen" tabindex="-1">Adressen einem Lernenden zuordnen <a class="header-anchor" href="#adressen-einem-lernenden-zuordnen" aria-label="Permalink to &quot;Adressen einem Lernenden zuordnen&quot;">​</a></h2><p><a href="/bilder/schueler/weitere-adressen1.png"><img src="'+d+'" alt="Das Verwaltungsfenster zu &quot;Weitere Adressen&quot;." loading="lazy"></a></p><p><em>Das Verwaltungsfenster zu &quot;Weitere Adressen&quot;.</em></p><p>In diesem Fenster verwalten Sie die weiteren Adressen der ausgewählten Person. Zu Beginn sind noch keine weiteren Adressen zugeordnet.</p><p>Wie in SchILD üblich kann ein bestehender Eintrag rechts im Detailfeld, hier die &quot;Ausgewählte Adresse&quot; bearbeitet oder eine neue über das &quot;<strong>+</strong>&quot; links oben im Feld &quot;Adressen&quot; hinzugefügt werden.</p><p>Hier bei den Details können eine <strong>Name</strong>, eine <strong>Ergänzung zum Namen</strong> bei langen Einträgen, die <strong>Anschrift</strong> und <strong>Telefonnummern</strong> wie <strong>Faxnummer</strong> und <strong>E-Mail</strong>adressen erfasst werden. Weiterhin lassen sich <strong>Bemerkungen</strong> frei eintragen, die <strong>Branche</strong>, bestimmte <strong>Ansprechpartner</strong> oder die betreuende Lehrkraft anlegen.</p><p>Beim Ansprechpartner lassen sich über das &quot;<strong>+</strong>&quot; mehrere Einträge anlegen.</p><p><a href="/bilder/schueler/weitere-adressen2.png"><img src="'+o+'" alt="Hier kann eine existierende Adresse gewählt oder eine neue angelegt werden." loading="lazy"></a></p><p><em>Hier kann eine existierende Adresse gewählt oder eine neue angelegt werden.</em></p><p>Klicken Sie links oben im Bereich <strong>Adressen</strong> auf <strong>+</strong>. Es öffnet sich eine Liste der bereits vorhandenen Adressen.</p><p>Sofern viele Kontakte im System erfasst sind, kann entweder über den Namen oder die Adresse gruppiert wurden.</p><p>Mit dem <strong>Filter</strong> grenzen Sie die Liste nach Name, Adresse oder Branche ein. Weitere Einschränkungen können Sie über die Kontrollkästchen auswählen.</p><p>Eine Adresse kann per Doppelklick dem Lernenden hinzugefügt werden, woraufhin sich auch dieses Fenster automatisch schließt.</p><p><a href="/bilder/schueler/weitere-adressen4.png"><img src="'+l+'" alt="Angaben zur Beschäftigung." loading="lazy"></a></p><p><em>Angaben zur Beschäftigung.</em></p><p>Unterhalb einer Adresse kann nun die <em>Art</em> und <em>Dauer der Beschäftigung</em> erfasst werden.</p><p>Ebenso lässt sich vermerken, ob es sich um ein Praktikum handelt.</p><p>Über das Feld <strong>Anschreiben</strong> lässt sich steuern, ob an diese Adresse ein Anschreiben an die hinterlegte Adresse erzeugt wird, wenn ein Report eine entsprechende Datenquelle verarbeitet.</p>',21),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Die Auswertung von "),e("strong",null,"Anschreiben"),n(" hängt vom verwendeten Report und dessen Datenquelle ab. Prüfen Sie die Empfängerauswahl in der Vorschau des konkreten Formulars.")])],-1),e("h2",{id:"anlegen-einer-neuen-adresse",tabindex:"-1"},[n("Anlegen einer neuen Adresse "),e("a",{class:"header-anchor",href:"#anlegen-einer-neuen-adresse","aria-label":'Permalink to "Anlegen einer neuen Adresse"'},"​")],-1),e("p",null,[e("a",{href:"/bilder/schueler/weitere-adressen3.png"},[e("img",{src:u,alt:"Legen Sie eine Adresse neu an.",loading:"lazy"})])],-1),e("p",null,[e("em",null,"Legen Sie eine Adresse neu an.")],-1),e("p",null,[n("Soll eine neue Adresse angelegt werden, ist die über das Feld "),e("strong",null,"Neueintrag"),n(" unten möglich.")],-1),e("p",null,"Es öffnet sich ein neues Fenster, in dem auf der rechten Seite alle Details einer neuen Adresse eingetragen werden kann.",-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n('Achten Sie darauf, dass als "Adressart" nur Adressarten eingeben werden können, die in '),e("em",null,"Kataloge ➜ Adressarten"),n(" zuvor schon angelegt wurden.")])],-1),s('<p>Neben den zu erwartenden Daten zu <em>Name</em>, <em>Adresse</em> und <em>Kontakten</em> lassen sich auf der rechten Seite per <em>Checkbox noch Eigenschaften</em> für diese Adresse setzen.</p><p>Etwa, ob es sich um einen <em>Praktikums-</em> oder <em>Ausbildungsbetrieb</em> handelt oder ob ein <em>Führungszeugnis</em> beziehungsweise eine <em>Belehrung nach dem Infektionsschutzgesetz</em> notwendig ist.</p><p>Unterhalb der Betriebsangaben erfassen Sie die <strong>Ansprechpartner</strong> mit ihren Kontaktdaten. Klicken Sie für einen neuen Eintrag auf <strong>+</strong>, tragen Sie die Daten ein und bestätigen Sie mit dem Haken.</p><p>Wurde die Aufnahme der neuen Adresse abgeschlossen, lässt sich dieses Fenster unten mit <code>Übernehmen</code> schließen.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Weitere_Adressen_(Sch%C3%BCler)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5919.</p>',6)])])}const k=i(c,[["render",g]]);export{w as __pageData,k as default};
